const $=s=>document.querySelector(s),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const e=escapeHTML;
const tg=window.Telegram?.WebApp;tg?.ready();tg?.expand();setupMobile();let trainerTab='all';let state,page=routeFromURL(),tab='groups',requestTab='pending',day=new Date(Date.now()+5*3600000).toISOString().slice(0,10),venueList=[],reportFrom=day.slice(0,7)+'-01',reportTo=day;const money=n=>new Intl.NumberFormat(locale(),{style:'currency',currency:'KZT'}).format(n/100);
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',cache:'no-store',headers:{'Content-Type':'application/json','X-Telegram-Init-Data':tg?.initData||''},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok)throw Error(result.error||window.t('Не удалось выполнить запрос'));return result}
function toast(text){$('#toast').textContent=window.t(text);$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(html){$('#dialog').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function closeDialog(){$('#dialog').close()}
async function mutate(action,data){try{state=await api('/api/action',{action,...data});await loadLanguage(state.user.language||'ru');closeDialog();render();toast(window.t('Сохранено'))}catch(error){toast(error.message)}}
function formDialog(title,fields,action,extra={}){modal(html`<h2>${e(title)}</h2><form class="fields">${fields}<div class="actions"><button class="primary">Сохранить</button><button type="button" onclick="closeDialog()">Отмена</button></div></form>`);$('#dialog form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button');button.disabled=true;const data=Object.fromEntries(new FormData(form));if(action==='group')data.days=new FormData(form).getAll('days').map(Number);if(['group','edit_group'].includes(action)){data.durationMinutes=Number(data.durationMinutes);data.members=new FormData(form).getAll('members').map(Number);}if(action==='payment')data.hours=Number(data.hours);await mutate(action,{...extra,...data});button.disabled=false}}
function heading(t,a=''){return html`<div class="heading"><h1>${e(t)}</h1>${a}</div>`}
function field(label,name,value='',type='text'){return html`<label>${e(label)}<input name="${name}" type="${type}" value="${e(value)}" required></label>`}
function render(){$('#theme').textContent='◐ '+window.t('Тема');const coach=state.user.role==='coach';$('#greeting').textContent=window.t('Приветствую, ')+state.user.fullName+' 👋';const items=coach?[['home','Главная'],['calendar','Календарь'],['groups','Группы'],['more','Ещё']]:[['home','Главное'],['trainers','Тренеры'],['profile','Профиль']];$('#nav').innerHTML=items.map(([p,label])=>html`<button class="${activeSection()===p?'active':''}" ${activeSection()===p?'aria-current="page"':''} onclick="navigate('${p}')">${window.t(label)}</button>`).join('');$('#screen').innerHTML=pageBack()+(page==='home'?(coach?coachHome():home()):page==='calendar'?calendarView():page==='student'?studentView():page==='more'?moreView():page==='requests'?requestsView():page==='groups'?groupsView():page==='trainers'?trainersView():page==='reports'?reportsView():page==='premium'?premiumView():page==='settings'?settingsView():profileView());syncBackButton()}
function moreView(){const pending=state.requests.filter(r=>r.status==='pending').length;return heading(window.t('Ещё'))+html`<div class="more-menu"><button class="card more-link" onclick="navigate('profile')"><span>👤 ${window.t('Профиль')}</span><span>→</span></button><button class="card more-link" onclick="navigate('requests')"><span>📩 ${window.t('Заявки')}</span><span>${pending?html`<b class="badge">${pending}</b>`:''} →</span></button><button class="card more-link" onclick="navigate('settings')"><span>⚙ ${window.t('Настройки')}</span><span>→</span></button></div>`}
function coachHome(){const today=new Date(Date.now()+5*3600000).toISOString().slice(0,10),sessions=state.sessions.filter(s=>s.date===today&&sessionStatus(s)!=='cancelled'),next=state.sessions.filter(s=>['live','scheduled'].includes(sessionStatus(s))).sort((a,b)=>a.begins-b.begins).slice(0,3),pending=state.requests.filter(r=>r.status==='pending').length;return heading(window.t('Главная'))+premiumBanner()+html`<div class="overview-stats"><button class="card" onclick="navigate('calendar')"><span>Тренировки сегодня</span><strong>${sessions.length}</strong></button><button class="card" onclick="navigate('requests')"><span>Новые заявки</span><strong>${pending}</strong></button></div><div class="section-title"><h2>Ближайшие тренировки</h2><button onclick="navigate('calendar')">Календарь →</button></div>${next.map(s=>html`<button class="card overview-session ${sessionStatus(s)==='live'?'live':''}" onclick="openSession('${s.id}')"><span><span class="badge">${status(s)}</span><strong>${e(s.name)}</strong><small>${e(s.date)} · ${e(s.time)} · ${s.durationMinutes||60} мин</small></span><span>→</span></button>`).join('')||html`<p class="empty">Ближайших тренировок нет.</p>`}`}

function sessionStatus(s,now=Date.now()/1000){return s.status==='cancelled'?'cancelled':s.status==='completed'||now>=s.ends?'completed':now>=s.begins?'live':'scheduled'}
function status(s){return {completed:window.t('Завершена'),cancelled:window.t('Отменена'),live:window.t('Тренировка идёт'),scheduled:window.t('Запланирована')}[sessionStatus(s)]}
function home(){const coach=state.user.role==='coach',uid=state.user.telegramId;let list=state.sessions.filter(s=>s.date===day).sort((a,b)=>(sessionStatus(a)==='completed')-(sessionStatus(b)==='completed')||a.begins-b.begins);const mine=state.students[0];return (coach?'':heading(window.t('Мои тренировки')))+(!coach?html`<div class="card hero-balance player-summary"><div><span>На балансе</span><strong>${balanceLabel(mine?.hours)}</strong></div><div><span>Оплачено тренеру</span><strong>${money(state.paidTotal||0)}</strong><small>За всё время · по записям тренера</small></div></div>`:'')+html`<div class="section-title"><h2>Расписание</h2><input aria-label="Дата календаря" class="calendar-date" type="date" value="${day}" onchange="day=this.value;render()"></div>${weekCalendar()}<div class="section-title"><h2>${new Date(day+'T12:00').toLocaleDateString(locale(),{day:'numeric',month:'long'})}</h2><span class="meta">${list.length} занятий</span></div>${list.map(s=>{const now=Date.now()/1000,current=sessionStatus(s,now),live=current==='live',soon=current==='scheduled'&&s.begins>now&&s.begins-now<=3600;const zero=state.students.filter(p=>s.members.includes(p.telegramId)&&p.hours===0&&!s.absent.includes(p.telegramId));return html`<div class="card session ${live?'live':current==='completed'?'completed':soon?'soon':''}"><div class="time">${s.time}<small>${s.durationMinutes||Math.round((s.ends-s.begins)/60)} мин</small></div><div class="body"><span class="badge">${soon?window.t('Скоро · ')+Math.ceil((s.begins-now)/60)+window.t(' мин'):status(s)}</span><h3>${e(s.name)}</h3><div class="meta">${e(s.place)}</div>${s.reason?html`<p>${e(s.reason)}. Часы не снимутся.</p>`:''}${coach&&['scheduled','live'].includes(current)&&s.begins-now<=86400&&zero.length?html`<div class="balance-warning">Нет часов: ${zero.map(p=>e(p.displayName||p.fullName)).join(', ')}<button onclick="tab='students';navigate('groups')">К ученикам</button></div>`:''}<div class="actions">${coach?html`<button onclick="openSession('${s.id}')">Открыть тренировку</button>`:current==='scheduled'?html`<button ${s.begins-now<86400||s.absent.includes(uid)?'disabled':''} onclick="mutate('absence',{id:'${s.id}'})">${s.absent.includes(uid)?window.t('Участие отменено'):window.t('Не приду')}</button>`:''}</div></div></div>`}).join('')||window.t('<p class="empty">На эту дату тренировок нет.</p>')}`}
function requestsView(){return heading(window.t('Заявки'),window.t('<div class="actions request-actions"><button onclick="refresh()" aria-label="Обновить заявки">↻</button><button onclick="exportGate()">↓ Выгрузить отчёт</button></div>'))+html`<div class="tabs">${[['pending',window.t('Входящие')],['accepted',window.t('Принятые')],['rejected',window.t('Отклонённые')]].map(([id,t])=>html`<button class="${requestTab===id?'active':''}" onclick="requestTab='${id}';render()">${t} · ${state.requests.filter(r=>r.status===id).length}</button>`).join('')}</div><div class="card">${state.requests.filter(r=>r.status===requestTab).map(r=>html`<div class="person"><div class="info"><strong>${e(r.playerName)}</strong><div class="student-comment">${e(r.comment)}</div></div>${r.status==='pending'?html`<button class="primary" onclick="mutate('decision',{id:'${r.id}',status:'accepted'})">Принять</button><button onclick="mutate('decision',{id:'${r.id}',status:'rejected'})">Отклонить</button>`:r.status==='accepted'?html`<button onclick="chat(${r.player})">Telegram-чат</button>`:''}</div>`).join('')||window.t('<p>Заявок пока нет.</p>')}</div>`}
function filterList(value){document.querySelectorAll('[data-search]').forEach(el=>el.hidden=!el.dataset.search.toLowerCase().includes(value.toLowerCase()))}
function groupsView(){return heading(window.t('Группы и ученики'),tab==='groups'?window.t('<button class="primary" onclick="newGroup()">+ Создать</button>'):'')+html`<div class="tabs"><button onclick="tab='groups';render()" class="${tab==='groups'?'active':''}">Группы · ${state.groups.length}</button><button onclick="tab='students';render()" class="${tab==='students'?'active':''}">Ученики · ${state.students.length}</button></div><label class="list-search">Поиск<input type="search" oninput="filterList(this.value)" placeholder="Имя или название"></label><div class="cards">${tab==='groups'?state.groups.map(g=>html`<article class="card live-group-card compact-group" data-search="${e(g.name)}" onclick="if(!event.target.closest('button'))groupDetail('${g.id}')" onkeydown="if(event.target===this&&(event.key==='Enter'||event.key===' ')){event.preventDefault();groupDetail('${g.id}')}" tabindex="0" aria-label="Открыть группу ${e(g.name)}"><div class="row"><span class="badge">${e(window.t(g.type))}</span><button aria-label="Действия с группой" onclick="event.stopPropagation();groupMenu('${g.id}')">⋯</button></div><h2>${e(g.name)}</h2><div class="meta">🗓 ${groupDays(g)} · ${g.time} · ${g.durationMinutes||60} мин</div><div class="compact-footer"><span>👥 ${g.members.length} уч.</span><span aria-hidden="true">Подробнее →</span></div></article>`).join('')||window.t('<p>Создайте первую группу. Учеников можно добавить позже.</p>'):[...state.students].sort((a,b)=>(b.hours===0)-(a.hours===0)).map(p=>{const groups=state.groups.filter(g=>g.members.includes(p.telegramId));return html`<div class="card student-card ${p.hours===0?'zero-hours':''}" data-search="${e((p.displayName||p.fullName)+' '+p.comment)}"><div class="row"><h3>${e(p.displayName||p.fullName)}</h3><strong class="hours-pill">${balanceLabel(p.hours)}</strong></div><span class="badge">${e(groups.map(g=>g.name).join(' · ')||window.t('Без группы'))}</span><p>${e(p.comment)}</p>${!p.hours?window.t('<p class="renewal-note">Часы закончились. Уточните продолжение занятий и примите оплату.</p>'):''}<div class="actions"><button class="primary" onclick="payment(${p.telegramId})">+ Часы и оплата</button><button onclick="assignMenu(${p.telegramId})">Добавить в группу</button><button onclick="renameStudent(${p.telegramId})">Изменить имя</button><button onclick="comment(${p.telegramId})">Комментарий</button><button onclick="chat(${p.telegramId})">Telegram</button></div></div>`}).join('')||window.t('<p>Примите заявку игрока — он появится здесь.</p>')}</div>`}
function groupMenu(id){const g=state.groups.find(g=>g.id===id);modal(html`<h2>${e(g.name)}</h2><div class="fields"><button onclick="editGroup('${id}')">Редактировать</button><button class="danger-text" onclick="deleteGroup('${id}')">Удалить</button><button onclick="closeDialog()">Закрыть</button></div>`)}
function rename(id){formDialog(window.t('Переименовать'),field(window.t('Название'),'name',state.groups.find(g=>g.id===id).name),'rename',{id})}
function deleteGroup(id){modal(html`<h2>Точно удалить группу?</h2><p>Группа исчезнет из списка, а её будущие тренировки будут отменены. Восстановить группу кнопкой будет нельзя.</p><p>Ученики, остатки часов, оплаты и завершённые занятия сохранятся.</p><div class="actions"><button class="danger-button" onclick="mutate('delete',{id:'${id}'})">Удалить</button><button onclick="closeDialog()">Отмена</button></div>`)}
function groupDays(g){return g.days.map(d=>[window.t('Вс'),window.t('Пн'),window.t('Вт'),window.t('Ср'),window.t('Чт'),window.t('Пт'),window.t('Сб')][d]).join(' · ')}
function groupDetail(id){const g=state.groups.find(g=>g.id===id),next=state.sessions.filter(s=>s.group===id&&s.status==='scheduled'&&s.ends>Date.now()/1000).sort((a,b)=>a.begins-b.begins)[0];modal(html`<span class="badge">🎾 ${e(window.t(g.type))}</span><h2>${e(g.name)}</h2><div class="group-facts"><div>📍 <strong>Место</strong><p>${e(g.place)}</p></div><div>🗓 <strong>Расписание</strong><p>${groupDays(g)} · ${g.time} · ${g.durationMinutes||60} мин</p></div><div>📅 <strong>Период</strong><p>${e(g.start)} — ${g.end?e(g.end):window.t('без даты окончания')}</p></div>${next?html`<div>⏱ <strong>Ближайшее занятие</strong><p>${next.date} в ${next.time}</p></div>`:''}</div><h3>👥 Ученики · ${g.members.length}</h3>${g.members.map(pid=>{const p=state.students.find(p=>p.telegramId===pid);return html`<div class="person"><div class="info"><strong>${e(p?.displayName||p?.fullName)}</strong><div class="student-comment">${e(p?.comment||'')}</div></div><span class="hours-pill">${balanceLabel(p?.hours)}</span></div>`}).join('')||window.t('<p>Учеников пока нет. Добавьте из принятых заявок.</p>')}<div class="actions"><button class="primary" onclick="addMember('${id}')">+ Добавить ученика</button><button onclick="closeDialog()">Закрыть</button></div>`)}
function addMember(id){const free=state.students.filter(p=>!state.groups.find(g=>g.id===id).members.includes(p.telegramId));modal(html`<h2>Добавить ученика</h2>${free.map(p=>html`<button class="pick" onclick="mutate('assign',{id:'${id}',player:${p.telegramId}})">${e(p.displayName||p.fullName)}<small>${e(p.comment)}</small></button>`).join('')||window.t('<p>Все принятые ученики уже добавлены в эту группу.</p>')}<button onclick="closeDialog()">Закрыть</button>`)}
function assignMenu(pid){modal(html`<h2>Выберите группу</h2>${state.groups.filter(g=>!g.members.includes(pid)&&(g.type==='Групповая'||!g.members.length)).map(g=>html`<button class="pick" onclick="mutate('assign',{id:'${g.id}',player:${pid}})">${e(g.name)} · ${g.time}</button>`).join('')||window.t('<p>Сначала создайте группу.</p>')}<button onclick="closeDialog()">Закрыть</button>`)}
async function newGroup(){try{venueList=await api('/api/venues?cityId='+state.user.cityId);formDialog(window.t('Новая группа'),field(window.t('Название'),'name')+html`<label>Тип<select name="type"><option value="${'Групповая'}">Групповая</option><option value="${'Индивидуальная'}">Индивидуальная</option></select></label><label>Клуб / корт<select onchange="this.form.elements.place.value=this.value"><option value="">Указать вручную</option>${venueList.map(v=>html`<option value="${e(v.name+' · '+v.address)}">${e(v.name+' · '+v.address)}</option>`).join('')}</select></label>`+field(window.t('Место и адрес'),'place',state.user.venue?[state.user.venue,state.user.address].filter(Boolean).join(' · '):'')+durationField()+field(window.t('Время'),'time','19:00','time')+html`<div class="days">${[1,2,3,4,5,6,0].map(d=>html`<label><input type="checkbox" name="days" value="${d}">${[window.t('Вс'),window.t('Пн'),window.t('Вт'),window.t('Ср'),window.t('Чт'),window.t('Пт'),window.t('Сб')][d]}</label>`).join('')}</div>`+field(window.t('Начало'),'start',day,'date')+window.t('<label>Окончание · необязательно<input type="date" name="end"></label>')+memberFields(),'group')}catch(err){toast(err.message)}}
function payment(pid){const p=state.students.find(p=>p.telegramId===pid);formDialog(window.t('Часы и оплата · ')+p.fullName,field(window.t('Часы'),'hours','','number')+field(window.t('Оплачено, ₸'),'amount','','number')+field(window.t('Дата оплаты'),'date',day,'date')+field(window.t('Кто оплатил'),'payer',p.fullName)+window.t('<label>Комментарий<textarea name="comment" maxlength="500"></textarea></label>'),'payment',{player:pid,nonce:crypto.randomUUID()});$('#dialog [name=hours]').min=1;$('#dialog [name=amount]').min=0;$('#dialog [name=amount]').step='.01'}
function comment(pid){formDialog(window.t('Комментарий тренера'),html`<label>Группа, дни и время<textarea name="comment" maxlength="500">${e(state.students.find(p=>p.telegramId===pid).comment)}</textarea></label>`,'comment',{player:pid})}
function chat(pid){const p=[...state.students,...state.trainers].find(p=>p.telegramId===pid);if(p?.username)(tg?.openTelegramLink?tg.openTelegramLink('https://t.me/'+p.username):window.open('https://t.me/'+p.username,'_blank','noopener'));else window.location.href='tg://user?id='+pid}
function openSession(id){const s=state.sessions.find(s=>s.id===id),current=sessionStatus(s);modal(html`<h2>${e(s.name)}</h2><span class="badge">${status(s)}</span><div class="session-facts"><span>🕒 ${e(s.time)} · ${s.durationMinutes||Math.round((s.ends-s.begins)/60)} мин</span><span>📍 ${e(s.place)}</span></div>${s.members.map(pid=>{const person=state.students.find(p=>p.telegramId===pid)||{};return html`<div class="person"><button class="person-open" onclick="navigateStudent(${pid})"><strong>${e(person.displayName||person.fullName)}</strong><small>${balanceLabel(person.hours)} →</small></button><label class="check attendance"><input type="checkbox" role="switch" ${s.absent.includes(pid)?'':'checked'} ${!['scheduled','live'].includes(current)?'disabled':''} onchange="updateAttendance('${s.id}',${pid},this)"><span class="switch-track"></span><span class="presence-label">${s.absent.includes(pid)?window.t('Отсутствует'):window.t('Присутствует')}</span></label></div>`}).join('')}<div class="actions">${current==='scheduled'?html`<button ${s.begins-Date.now()/1000<=86400?'disabled':''} onclick="cancel('${id}')">Отменить тренировку</button>`:''}<button class="primary" onclick="closeDialog()">Закрыть</button></div>`)}
function cancel(id){formDialog(window.t('Отмена тренировки'),window.t('<label>Причина<textarea name="reason" required maxlength="500"></textarea></label><p>Все участники получат причину отмены. Часы не снимутся.</p>'),'cancel',{id})}
function trainerRelation(id){return state.requests.find(r=>r.coach===id&&r.status!=='rejected')}
function trainersView(){const mine=state.trainers.filter(t=>trainerRelation(t.telegramId)?.status==='accepted'),list=trainerTab==='mine'?mine:state.trainers;return heading(window.t('Тренеры · ')+state.user.city)+html`<div class="tabs"><button class="${trainerTab==='all'?'active':''}" onclick="trainerTab='all';render()">Все · ${state.trainers.length}</button><button class="${trainerTab==='mine'?'active':''}" onclick="trainerTab='mine';render()">Мои тренеры · ${mine.length}</button></div><label class="list-search">Поиск<input type="search" oninput="filterList(this.value)" placeholder="Имя тренера"></label><div class="cards">${list.map(t=>html`<article class="card trainer-card" data-search="${e(t.fullName)}"><div class="row"><div class="avatar">${e(t.fullName.slice(0,1))}</div><div class="info"><h2>${e(t.fullName)}</h2><span class="meta">📍 ${e(t.city)}</span></div></div><p class="trainer-venue">🎾 ${e(t.venue||window.t('Площадка уточняется'))}</p><p class="bio-preview">${e(t.bio||window.t('Тренер пока не добавил описание.'))}</p><div class="card-foot"><span class="badge">${trainerRelation(t.telegramId)?.status==='accepted'?window.t('Ваш тренер'):trainerRelation(t.telegramId)?window.t('Заявка отправлена'):window.t('Теннис')}</span><button onclick="trainerDetail(${t.telegramId})">Подробнее →</button></div></article>`).join('')||html`<div class="card empty">${trainerTab==='mine'?window.t('После принятия заявки здесь появится ваш тренер.'):window.t('Тренеров в этом городе пока нет.')}</div>`}</div>`}
function trainerDetail(id){const t=state.trainers.find(t=>t.telegramId===id),r=trainerRelation(id);modal(html`<span class="badge">🎾 Тренер по теннису</span><h2>${e(t.fullName)}</h2><div class="group-facts"><div>📍 ${e(t.city)}<p>${e(t.venue||window.t('Площадка уточняется'))}<br>${e(t.address||'')}</p></div></div><h3>О тренере</h3><p class="trainer-bio">${e(t.bio||window.t('Описание пока не заполнено.'))}</p><div class="actions">${r?.status==='accepted'?html`<button class="primary" onclick="chat(${id})">Написать тренеру</button>`:r?window.t('<span class="badge">Заявка отправлена</span>'):html`<button class="primary" onclick="requestTrainer(${id})">Отправить заявку</button>`}<button onclick="closeDialog()">Закрыть</button></div>`)}
function premiumBanner(){return html`<button class="premium-banner" onclick="navigate('premium')"><span><small>TOPCOACH PREMIUM</small><strong>Больше возможностей для тренера</strong><span>Сравнить базовый план и Premium</span></span><b aria-hidden="true">↗</b></button>`}
function requestTrainer(id){formDialog(window.t('Заявка тренеру'),window.t('<p>Отправляйте заявку после договорённости с тренером и оплаты.</p><label>Комментарий: группа, дни, время<textarea name="comment" maxlength="500"></textarea></label>'),'request',{coach:id})}
function profileView(){const u=state.user;setTimeout(()=>{const f=$('#profile');if(f&&u.role==='coach')loadProfileVenues(f,false);if(f)f.onsubmit=async ev=>{ev.preventDefault();try{state.user=await api('/api/me',Object.fromEntries(new FormData(f)));render();toast(window.t('Профиль сохранён'))}catch(err){toast(err.message)}}},0);return heading(window.t('Профиль'),u.role==='coach'?window.t('<div class="actions"><button onclick="navigate(\'reports\')">Оплаты и выручка</button><button onclick="navigate(\'settings\')">⚙ Настройки</button></div>'):'')+html`<form id="profile" class="card fields">${field(window.t('ФИО'),'fullName',u.fullName)}<label>Город<input value="${e(u.city)}" readonly><input name="cityId" type="hidden" value="${e(u.cityId)}"></label>${u.role==='coach'?html`<label>Клуб / корт<select name="venueId" onchange="selectProfileVenue(this.form)"><option value="">Загрузка справочника…</option></select></label><label>Название площадки<input name="venue" value="${e(u.venue||u.customVenue||'')}"></label><label>Адрес<input name="address" value="${e(u.address||'')}"></label>`:''}<label>О себе<textarea name="bio" maxlength="1000" placeholder="${u.role==='coach'?window.t('Что вы тренируете, стоимость индивидуальных и групповых занятий'):window.t('Расскажите о своём уровне игры, опыте и целях занятий')}">${e(u.bio)}</textarea></label><button class="primary">Сохранить</button></form>`}
function reportPeriod(kind){reportTo=new Date(Date.now()+5*3600000).toISOString().slice(0,10);reportFrom=kind==='year'?reportTo.slice(0,4)+'-01-01':reportTo.slice(0,7)+'-01';render()}
function reportsView(){const valid=reportFrom<=reportTo,list=valid?state.payments.filter(p=>p.date>=reportFrom&&p.date<=reportTo).sort((a,b)=>b.created-a.created):[];return heading(window.t('Оплаты и выручка'))+html`<section class="card revenue-summary"><span>Получено за период</span><h2>${money(list.reduce((n,p)=>n+p.amount,0))}</h2><span>${list.length} оплат · ${list.reduce((n,p)=>n+p.hours,0)} ч начислено</span></section><div class="card report-filters"><div class="tabs"><button onclick="reportPeriod('month')">Этот месяц</button><button onclick="reportPeriod('year')">Этот год</button></div><div class="date-range"><label>С<input type="date" value="${reportFrom}" onchange="reportFrom=this.value;render()"></label><label>По<input type="date" value="${reportTo}" onchange="reportTo=this.value;render()"></label></div>${valid?'':window.t('<p role="alert">Проверьте порядок дат.</p>')}</div><h2>История оплат</h2><div class="payment-list">${list.map(p=>html`<article class="card payment-card"><div class="row"><strong>${e(p.name)}</strong><strong class="payment-sum">${money(p.amount)}</strong></div><div class="payment-tags"><span class="badge">+${balanceLabel(p.hours)}</span><span class="meta">${new Date(p.date+'T12:00').toLocaleDateString(locale())}</span></div><div class="meta">${paymentGroupLabel(p)}</div><div class="payment-detail">Оплатил: ${e(p.payer)}${p.comment?html`<p>${e(p.comment)}</p>`:''}</div></article>`).join('')||window.t('<div class="card empty">За выбранный период оплат нет.</div>')}</div>`}
function exportGate(){modal(window.t('<h2>Выгрузка доступна в Premium</h2><p>Отчёты по заявкам, группам и оплатам.</p><div class="actions"><button class="primary" onclick="closeDialog();navigate(\'premium\')">Подробнее</button><button onclick="closeDialog()">Закрыть</button></div>'))}
function premiumView(){return html`<section class="premium-hero"><span>TOPCOACH PREMIUM</span><h1>Тренируйте больше.<br>Рутину оставьте нам.</h1><p>Базовый план — для ежедневной работы. Premium — для анализа и роста вашей практики.</p></section><div class="plans"><section class="card plan"><span class="badge">ВАШ ПЛАН</span><h2>Базовый</h2><div class="plan-price">Бесплатно</div><ul><li>👥 Заявки и список учеников</li><li>🎾 Групповые и индивидуальные занятия</li><li>🗓 Календарь и посещаемость</li><li>⏱ Баланс и автоматическое списание часов</li><li>💳 Учёт оплат и выручка за период</li><li>🔔 Уведомления о занятиях, оплатах и отменах</li></ul><p class="meta">Всё для организации тренировок каждый день.</p></section><section class="card plan premium-plan"><span class="badge">СКОРО</span><h2>Premium</h2><div class="plan-price">Больше контроля</div><ul><li>✅ Всё из базового плана</li><li>📥 Выгрузка заявок, групп и оплат</li><li>📊 Подробная аналитика по группам и типам занятий</li><li>📈 Сравнение периодов и динамика выручки</li><li>🗂 Отчёты для работы вне приложения</li></ul><p class="meta">Планируемые преимущества. Цена и лимиты будут объявлены перед запуском.</p><button disabled>Подписка готовится к запуску</button></section></div>`}
let profileVenueRows=[];
async function loadProfileVenues(form,clear){if(!form.elements.venueId)return;const cityId=form.elements.cityId.value;if(clear){form.elements.venue.value='';form.elements.address.value='';}const select=form.elements.venueId;select.disabled=true;select.innerHTML=window.t('<option value="">Загрузка…</option>');form.querySelector('button[type=submit],button.primary').disabled=true;try{const rows=await api('/api/venues?cityId='+encodeURIComponent(cityId));if(!form.isConnected||form.elements.cityId.value!==cityId)return;profileVenueRows=rows;const match=clear?null:rows.find(v=>v.name===form.elements.venue.value&&v.address===form.elements.address.value);select.innerHTML=window.t('<option value="">Указать вручную</option>')+rows.map(v=>html`<option value="${v.id}" ${match?.id===v.id?'selected':''}>${e(v.name)} · ${e(v.address)}</option>`).join('');}catch(error){select.innerHTML=window.t('<option value="">Указать вручную</option>');toast(window.t('Не удалось загрузить корты. Можно указать вручную.'))}finally{if(form.isConnected&&form.elements.cityId.value===cityId){select.disabled=false;form.querySelector('button[type=submit],button.primary').disabled=false}}}
function selectProfileVenue(form){const v=profileVenueRows.find(v=>v.id===form.elements.venueId.value);form.elements.venue.value=v?.name||'';form.elements.address.value=v?.address||''}
function setupMobile(){if(!tg)return;try{if(tg.isVersionAtLeast?.('6.2'))tg.enableClosingConfirmation();if(tg.isVersionAtLeast?.('7.7'))tg.disableVerticalSwipes();if(tg.isVersionAtLeast?.('8.0'))tg.requestFullscreen()}catch{}const safe=()=>{const top=(tg.safeAreaInset?.top||0)+(tg.contentSafeAreaInset?.top||0);document.documentElement.style.setProperty('--tg-top',top+'px');document.documentElement.style.setProperty('--tg-bottom',(tg.safeAreaInset?.bottom||0)+'px')};safe();tg.onEvent?.('safeAreaChanged',safe);tg.onEvent?.('contentSafeAreaChanged',safe)}
$('#theme').onclick=()=>document.body.classList.toggle('dark');let refreshing=false;
async function refresh(silent=false){if(refreshing)return;refreshing=true;try{const next=await api('/api/state');if(silent&&($('#dialog').open||document.activeElement?.matches('input,textarea,select')))return;const changed=JSON.stringify(state)!==JSON.stringify(next);await loadLanguage(next.user.language||'ru');state=next;initNavigation();if(changed||!silent||['home','calendar'].includes(page)){const scroll=window.scrollY;render();if(silent)window.scrollTo(0,scroll)}}catch(err){if(!state)$('#screen').textContent=err.message;else if(!silent)toast(err.message)}finally{refreshing=false}}
refresh();setInterval(()=>{if(state&&!document.hidden&&!$('#dialog').open&&['home','calendar','more','requests','groups','trainers'].includes(page))refresh(true)},5000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state&&!$('#dialog').open)refresh(true)});

function weekCalendar(){const selected=new Date(day+'T12:00:00Z');const monday=new Date(selected);monday.setUTCDate(selected.getUTCDate()-(selected.getUTCDay()+6)%7);return html`<div class="week">${Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setUTCDate(d.getUTCDate()+i);const value=d.toISOString().slice(0,10);return html`<button class="${value===day?'selected':''}" onclick="day='${value}';render()"><small>${d.toLocaleDateString(locale(),{weekday:'short',timeZone:'UTC'})}</small><b>${d.getUTCDate()}</b></button>`}).join('')}</div>`}
function renameStudent(pid){const p=state.students.find(p=>p.telegramId===pid);formDialog(window.t('Имя ученика'),field(window.t('ФИО'),'name',p.displayName||p.fullName)+window.t('<p>Это имя в вашем списке. Telegram-профиль ученика не изменится.</p>'),'student_name',{player:pid})}
async function updateAttendance(id,pid,input){const present=input.checked;input.disabled=true;try{state=await api('/api/action',{action:'attendance',id,player:pid,present});input.closest('label').querySelector('.presence-label').textContent=present?window.t('Присутствует'):window.t('Отсутствует');render()}catch(error){input.checked=!present;toast(error.message)}finally{input.disabled=false}}

function paymentGroupLabel(payment){const groups=state.groups.filter(g=>g.members.includes(payment.player));return groups.length?groups.map(g=>e(g.name)+' · '+e(window.t(g.type))).join('; '):window.t('Ученик пока без группы')}

function durationField(value=60){return html`<label>Длительность тренировки, минут<input type="number" name="durationMinutes" min="60" max="1440" step="1" value="${Math.max(60,value)}" required><small class="meta">Минимум 60 минут. Например: 60, 90 или 120.</small></label>`}
function memberFields(group){const list=state.students.filter(p=>!group?.members.includes(p.telegramId));return html`<fieldset><legend>Добавить учеников · необязательно</legend>${list.map(p=>html`<label class="check"><input type="checkbox" name="members" value="${p.telegramId}"><span>${e(p.displayName||p.fullName)}<small class="meta"> ${e(p.comment||'')} · ${e(state.groups.filter(g=>g.members.includes(p.telegramId)).map(g=>g.name).join(', ')||window.t('Без группы'))}</small></span></label>`).join('')||window.t('<p>Нет учеников для добавления.</p>')}</fieldset>`}
function editGroup(id){const g=state.groups.find(g=>g.id===id);formDialog(window.t('Редактировать группу'),field(window.t('Название'),'name',g.name)+durationField(g.durationMinutes||60)+window.t('<p>Длительность изменится у будущих тренировок. Начавшиеся и завершённые занятия сохранят прежнюю длительность.</p>')+memberFields(g),'edit_group',{id})}

function balanceLabel(hours){const minutes=Math.round((hours||0)*60),h=Math.floor(minutes/60),m=minutes%60;return [h?html`${h} ч`:'',m?html`${m} мин`:''].filter(Boolean).join(' ')||window.t('0 ч')}

function settingsView(){return heading(window.t('Настройки'))+html`<form class="card fields" onsubmit="saveSettings(event)"><h2>Уведомления и язык</h2><label>Напомнить о тренировке<select name="reminderHours"><option value="1" ${state.user.reminderHours===1?'selected':''}>За 1 час</option><option value="3" ${state.user.reminderHours!==1?'selected':''}>За 3 часа</option></select></label><p class="meta">Напоминание применяется к тренеру и ученикам его групп.</p><label>Язык<select name="language"><option value="ru" ${uiLanguage==='ru'?'selected':''}>Русский</option><option value="kaz" ${uiLanguage==='kaz'?'selected':''}>Қазақша</option><option value="en" ${uiLanguage==='en'?'selected':''}>English</option></select></label><button class="primary">Сохранить</button><button type="button" onclick="goBack()">Назад</button></form>`}
async function saveSettings(event){event.preventDefault();const form=event.target,button=form.querySelector('button');button.disabled=true;const values=Object.fromEntries(new FormData(form));await mutate('settings',{language:values.language,reminderHours:Number(values.reminderHours)});if(button.isConnected)button.disabled=false}

function studentView(){const id=Number(new URL(window.location.href).searchParams.get('studentId')),student=state.students.find(person=>person.telegramId===id);if(!student){navigate('groups');return ''}const groups=state.groups.filter(group=>group.members.includes(id));const sessions=state.sessions.filter(session=>session.members.includes(id)).sort((a,b)=>b.begins-a.begins).slice(0,4);return heading(e(student.displayName||student.fullName))+html`<section class="student-profile"><div class="card student-profile-summary"><div class="avatar student-avatar">${e((student.displayName||student.fullName).slice(0,1))}</div><div><span class="meta">Баланс ученика</span><strong>${balanceLabel(student.hours)}</strong><p>${e(student.comment||'Комментарий не добавлен.')}</p></div></div><div class="student-profile-actions"><button class="primary" onclick="payment(${id})">+ Часы и оплата</button><button onclick="renameStudent(${id})">Изменить имя</button><button onclick="comment(${id})">Комментарий</button><button onclick="chat(${id})">Telegram</button></div><section class="card"><h2>Группы</h2>${groups.map(group=>html`<button class="student-group-link" onclick="groupDetail('${group.id}')"><span>${e(group.name)}</span><small>${e(group.time)} · ${group.durationMinutes||60} мин →</small></button>`).join('')||html`<p>Ученик пока не добавлен в группу.</p>`}</section><section class="card"><h2>Последние тренировки</h2>${sessions.map(session=>html`<button class="student-session-link" onclick="openSession('${session.id}')"><span>${e(session.date)} · ${e(session.time)}</span><small>${e(session.name)} · ${status(session)} →</small></button>`).join('')||html`<p>Тренировок пока нет.</p>`}</section></section>`}

function setupPhonePreview(){const button=$('#phone-preview');if(!button)return;const key='topcoach-phone-preview';const saved=(()=>{try{return localStorage.getItem(key)==='1'}catch{return false}})();const update=enabled=>{document.body.classList.toggle('phone-preview',enabled);button.setAttribute('aria-pressed',String(enabled));button.textContent=enabled?'▣ Полный экран':'▣ Телефон'};update(saved);button.onclick=()=>{const enabled=!document.body.classList.contains('phone-preview');try{localStorage.setItem(key,enabled?'1':'0')}catch{}update(enabled)}}
setupPhonePreview();
